function validate([n, edges]) {
  if (!Number.isInteger(n) || n < 2 || n > 50000) return 'n is between 2 and 5 * 10^4.';
  if (!Array.isArray(edges) || edges.length < 1 || edges.length > Math.min(50000, (n * (n - 1)) / 2)) return 'edges needs 1 to min(5 * 10^4, n * (n - 1) / 2) entries.';
  const seen = new Set();
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 3) return 'Each edge is [a, b, w].';
    const [a, b, w] = edge;
    if (![a, b].every(v => Number.isInteger(v) && v >= 0 && v < n)) return 'Edge endpoints must be nodes 0 to n - 1.';
    if (a === b) return 'An edge cannot join a node to itself.';
    if (!Number.isInteger(w) || w < 1 || w > 100000) return 'Each weight is between 1 and 10^5.';
    const key = Math.min(a, b) * n + Math.max(a, b);
    if (seen.has(key)) return 'No two edges may join the same pair of nodes.';
    seen.add(key);
  }
  return null;
}

