function findAnswer(n, edges) {
  const graph = Array.from({ length: n }, () => []);
  for (const [a, b, w] of edges) {
    graph[a].push([b, w]);
    graph[b].push([a, w]);
  }
  const push = (heap, item) => {
    heap.push(item);
    let i = heap.length - 1;
    while (i > 0 && heap[(i - 1) >> 1][0] > heap[i][0]) {
      const parent = (i - 1) >> 1;
      [heap[i], heap[parent]] = [heap[parent], heap[i]];
      i = parent;
    }
  };
  const pop = (heap) => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        let smallest = i;
        for (const child of [2 * i + 1, 2 * i + 2]) {
          if (child < heap.length && heap[child][0] < heap[smallest][0]) smallest = child;
        }
        if (smallest === i) break;
        [heap[i], heap[smallest]] = [heap[smallest], heap[i]];
        i = smallest;
      }
    }
    return top;
  };
  const dijkstra = (source) => {
    const dist = new Array(n).fill(Infinity);
    dist[source] = 0;
    const heap = [[0, source]];
    while (heap.length > 0) {
      const [d, node] = pop(heap);
      if (d > dist[node]) continue;
      for (const [next, w] of graph[node]) {
        if (d + w < dist[next]) {
          dist[next] = d + w;
          push(heap, [dist[next], next]);
        }
      }
    }
    return dist;
  };
  const fromStart = dijkstra(0);
  const fromEnd = dijkstra(n - 1);
  const best = fromStart[n - 1];
  return edges.map(([a, b, w]) =>
    best !== Infinity &&
    (fromStart[a] + w + fromEnd[b] === best || fromStart[b] + w + fromEnd[a] === best));
}

