function findAnswer(n, edges) {
  // Enumerate every simple path from 0 to n - 1 and keep the edge sets of the lightest ones.
  const answer = edges.map(() => false);
  let bestLength = Infinity;
  let bestPaths = [];
  const visited = new Array(n).fill(false);
  const used = [];
  const walk = (node, length) => {
    if (node === n - 1) {
      if (length < bestLength) { bestLength = length; bestPaths = []; }
      if (length === bestLength) bestPaths.push([...used]);
      return;
    }
    visited[node] = true;
    edges.forEach(([a, b, w], index) => {
      const other = a === node ? b : b === node ? a : -1;
      if (other >= 0 && !visited[other]) {
        used.push(index);
        walk(other, length + w);
        used.pop();
      }
    });
    visited[node] = false;
  };
  walk(0, 0);
  for (const path of bestPaths) for (const index of path) answer[index] = true;
  return answer;
}

