function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(500, 1500) : int(2, 7);
  const maxEdges = Math.min(size === 'large' ? 2000 : 11, (n * (n - 1)) / 2);
  const m = size === 'large' ? maxEdges : int(1, maxEdges);
  const maxWeight = size === 'large' ? (rand() < 0.5 ? 3 : 100000) : (rand() < 0.7 ? 3 : 20);
  const seen = new Set();
  const edges = [];
  // Large graphs get a random chain from 0 to n - 1 first so the target is usually reachable.
  if (size === 'large') {
    const middle = Array.from({ length: n - 2 }, (_, i) => i + 1).filter(() => rand() < 0.02);
    const chain = [0, ...middle, n - 1];
    for (let i = 0; i + 1 < chain.length; i++) {
      const a = chain[i], b = chain[i + 1];
      seen.add(Math.min(a, b) * n + Math.max(a, b));
      edges.push([a, b, int(1, maxWeight)]);
    }
  }
  while (edges.length < m) {
    const a = int(0, n - 1), b = int(0, n - 1);
    const key = Math.min(a, b) * n + Math.max(a, b);
    if (a === b || seen.has(key)) continue;
    seen.add(key);
    edges.push([a, b, int(1, maxWeight)]);
  }
  for (let i = edges.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [edges[i], edges[j]] = [edges[j], edges[i]];
  }
  return [n, edges];
}
